/** Smallest publishable cell (coarsest grid's minN). */
export const HYROX_S79_MIN_CELL_N = 119;
/** Timing-consistency tolerance (seconds); see header rule 5. */
export const HYROX_S79_CONSISTENCY_TOLERANCE_SEC = 17;

